import sys
from math import sqrt

def isqrt(n):
    if n < 0:
        return -1
    x = int(sqrt(n))
    while x * x > n:
        x -= 1
    while (x + 1) * (x + 1) <= n:
        x += 1
    return x

def main():
    data = sys.stdin.read().split()
    if len(data) < 2:
        return
    A = int(data[0])
    B = int(data[1])
    out = "-1 -1"
    if A % 2 == 0:
        # Room W x L: blue border A = 2W + 2L - 4, white interior B = (W-2)(L-2)
        # Let u = W-2, v = L-2: u*v = B, u+v = (A-4)/2
        s = (A - 4) // 2  # u + v
        if s >= 2:
            d = s * s - 4 * B  # discriminant
            if d >= 0:
                r = isqrt(d)
                if r * r == d and (s - r) % 2 == 0:
                    u = (s - r) // 2
                    v = (s + r) // 2
                    if u >= 1:  # interior must be non-empty (u <= v)
                        out = "%d %d" % (u + 2, v + 2)
    sys.stdout.write(out + "\n")

